<?php
namespace App\Http\Controllers\Admin;

use App\Http\Controllers\Controller;
use App\Domain\Marketing\MarketingPermission as Permission;
use App\Services\Marketing\Audience\{AudienceDirectory,AudienceSegments,AudienceTasks};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Storage};
use Illuminate\Support\Str;
use Illuminate\Validation\Rule;

class MarketingAudienceController extends Controller
{
 private function row($query,string $id){$row=$query->where('id',$id)->first();abort_unless($row,404);return $row;}
 private function access(Request $r,string $p=Permission::VIEW_AUDIENCE):void {abort_unless(Permission::allows($r->user(),Permission::VIEW_AUDIENCE)&&Permission::allows($r->user(),$p),403);}
 private function dir():AudienceDirectory{return app(AudienceDirectory::class);}
 private function tasks():AudienceTasks{return app(AudienceTasks::class);}
 private function segment(string $id){return $this->row(DB::table('marketing_audience_segments')->where('merchant_key',$this->dir()->merchant()),$id);}
 private function task(Request $r,string $id){$t=$this->row(DB::table('marketing_audience_tasks')->where('merchant_key',$this->dir()->merchant()),$id);abort_unless($t->user_id===$r->user()->id||$r->user()->is_super_admin||$t->kind==='sync',403);return $t;}
 public function page(Request $r,string $page='contacts'){$this->access($r);abort_unless(in_array($page,['contacts','segments','import','export']),404);$manage=Permission::allows($r->user(),Permission::MANAGE_AUDIENCE);$export=Permission::allows($r->user(),Permission::EXPORT_AUDIENCE);return view('marketing.audience.index',compact('page','manage','export'));}
 public function segmentPage(Request $r,?string $id=null){
  $this->access($r,Permission::MANAGE_AUDIENCE);$page='segment-builder';$manage=true;$export=false;
  $presets=app(\App\Services\Marketing\Audience\AudienceSegmentPresets::class)->all();$preset=$r->query('preset');
  abort_if($preset!==null&&(!isset($presets[$preset])||!$presets[$preset]['available']),422,'Choose an available preset.');
  $segment=$id?$this->segment($id):null;abort_if($segment?->archived_at,409,'Restore this segment before editing.');
  $builder=$segment||$preset!==null;$selectedPreset=$preset!==null?$presets[$preset]:null;
  if($segment)$segment->rules=json_decode($segment->rules,true);
  $categories=DB::table('categories')->orderBy('name')->get(['id','name']);
  return view('marketing.audience.index',compact('page','manage','export','presets','builder','selectedPreset','segment','categories'));
 }
 public function contacts(Request $r){
  $this->access($r);$f=$this->filters($r);$q=$this->dir()->applyFilters($this->dir()->query(),$f);$page=$q->orderBy('name')->orderBy('id')->paginate($f['per_page']??25);$data=$this->dir()->decorateMany($page->getCollection());
  $all=$this->dir()->query();$suppressed=clone $all;app(AudienceSegments::class)->condition($suppressed,['field'=>'subscription','operator'=>'eq','channel'=>'email','value'=>'suppressed']);
  return response()->json(['data'=>$data,'total'=>$page->total(),'page'=>$page->currentPage(),'last_page'=>$page->lastPage(),'summary'=>['total'=>(clone $all)->count(),'subscribers'=>app(AudienceSegments::class)->eligible(clone $all,'email')->count(),'with_orders'=>(clone $all)->where('paid_orders','>',0)->count(),'suppressed'=>$suppressed->count()],'last_sync'=>DB::table('marketing_audience_tasks')->where('merchant_key',$this->dir()->merchant())->where('kind','sync')->where('state','completed')->max('updated_at')]);
 }
 public function detail(Request $r,string $id){$this->access($r);return response()->json($this->dir()->decorate($this->row($this->dir()->query(),$id)));}
 public function sync(Request $r){$this->access($r,Permission::MANAGE_AUDIENCE);return response()->json(['id'=>$this->tasks()->start($r->user(),'sync')],202);}
 public function segments(Request $r){$this->access($r);$q=DB::table('marketing_audience_segments')->where('merchant_key',$this->dir()->merchant());$f=$r->validate(['q'=>'nullable|string|max:120','status'=>['nullable',Rule::in(['active','draft','archived'])],'per_page'=>['nullable',Rule::in([25,50,100])]]);if(in_array($f['status']??'',['active','draft'],true))$q->whereNull('archived_at')->where('status',$f['status']);elseif(($f['status']??'')==='archived')$q->whereNotNull('archived_at');if(trim($f['q']??'')!=='')$q->where('name','like','%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],trim($f['q'])).'%');$items=$q->orderBy('name')->orderBy('id')->paginate($f['per_page']??25);$items->getCollection()->transform(function($s){$s->rules=json_decode($s->rules,true);return $s;});return response()->json($items);}
 public function saveSegment(Request $r,?string $id=null){
  $this->access($r,Permission::MANAGE_AUDIENCE);$d=$r->validate(['name'=>'required|string|max:120','version'=>'required|integer|min:0','rules'=>'required|array','description'=>'nullable|string|max:2000','status'=>['nullable',Rule::in(['active','draft','archived'])]]);$rules=app(AudienceSegments::class)->validate($d['rules']);
  return DB::transaction(function()use($r,$d,$rules,$id){$s=null;if($id){DB::table('marketing_audience_segments')->where('id',$id)->lockForUpdate()->first();$s=$this->segment($id);}abort_if(($s?->version??0)!==(int)$d['version']||$s?->archived_at,409,'This segment changed. Reload before saving.');$key=$id??(string)Str::uuid();DB::table('marketing_audience_segments')->updateOrInsert(['id'=>$key],['merchant_key'=>$this->dir()->merchant(),'user_id'=>$r->user()->id,'name'=>$d['name'],'description'=>$d['description']??null,'status'=>($d['status']??'active')==='archived'?'active':($d['status']??'active'),'archived_at'=>($d['status']??'active')==='archived'?now():null,'rules'=>json_encode($rules),'version'=>($s?->version??0)+1,'created_at'=>$s?->created_at??now(),'updated_at'=>now()]);$this->tasks()->audit($r->user()->id,'segment_saved',$key);return response()->json(['id'=>$key],$id?200:201);});
 }
 public function segmentAction(Request $r,string $id,string $action){
  $this->access($r,Permission::MANAGE_AUDIENCE);return DB::transaction(function()use($r,$id,$action){DB::table('marketing_audience_segments')->where('id',$id)->lockForUpdate()->first();$s=$this->segment($id);$r->validate(['version'=>'required|integer']);abort_unless($s->version===(int)$r->input('version'),409,'This segment changed. Reload first.');if($action==='duplicate'){$key=(string)Str::uuid();$copy=(array)$s;$copy['id']=$key;$copy['name']=mb_substr($s->name.' (copy)',0,120);$copy['version']=1;$copy['archived_at']=null;$copy['created_at']=$copy['updated_at']=now();$copy['user_id']=$r->user()->id;DB::table('marketing_audience_segments')->insert($copy);}else{$key=$id;DB::table('marketing_audience_segments')->where('id',$id)->update(['archived_at'=>$action==='archive'?now():null,'version'=>$s->version+1,'updated_at'=>now()]);}$this->tasks()->audit($r->user()->id,'segment_'.$action,$key);return response()->json(['id'=>$key]);});
 }
 public function preview(Request $r){$this->access($r);$d=$r->validate(['rules'=>'required|array']);$q=app(AudienceSegments::class)->apply($this->dir()->query(),$d['rules']);$counts=app(AudienceSegments::class)->preview(clone $q);$counts['samples']=(clone $q)->orderBy('name')->orderBy('id')->limit(5)->get(['id','name','email']);return response()->json($counts);}
 public function recipients(Request $r,string $id){$this->access($r);$s=$this->segment($id);abort_if($s->archived_at||($s->status??'active')!=='active',409,'Activate or restore this segment before using it.');return response()->json(['segment_id'=>$s->id,'name'=>$s->name,'version'=>$s->version,'counts'=>app(AudienceSegments::class)->preview(app(AudienceSegments::class)->apply($this->dir()->query(),json_decode($s->rules,true))),'delivery_enabled'=>false]);}
 public function subscription(Request $r,string $id){$this->access($r,Permission::MANAGE_AUDIENCE);$c=$this->row($this->dir()->query(),$id);$d=$r->validate(['channel'=>['required',Rule::in(['email','sms','whatsapp','global'])],'status'=>['required',Rule::in(['unsubscribed','suppressed'])]]);$dest=$d['channel']==='email'?$c->email:($d['channel']==='global'?($c->email?:$c->phone):$c->phone);abort_unless($dest,422,'This contact has no matching destination.');DB::transaction(function()use($r,$d,$dest,$id){DB::table('marketing_audience_locks')->where('merchant_key',$this->dir()->merchant())->lockForUpdate()->first();$this->dir()->subscribe($d['channel'],$dest,$d['status'],'staff:'.$r->user()->id,now());$this->tasks()->audit($r->user()->id,'subscription_'.$d['status'],$id,['channel'=>$d['channel']]);});return response()->json(['saved'=>true]);}
 public function upload(Request $r){
  $this->access($r,Permission::MANAGE_AUDIENCE);$d=$r->validate(['file'=>'required|file|max:2048','mapping'=>'required|array','mapping.email'=>'nullable|string|max:100','mapping.phone'=>'nullable|string|max:100','mapping.name'=>'nullable|string|max:100','mapping.tags'=>'nullable|string|max:100']);$f=$r->file('file');abort_unless(strtolower($f->getClientOriginalExtension())==='csv',422,'Upload a UTF-8 CSV file.');$h=fopen($f->getRealPath(),'r');$headers=fgetcsv($h,0,',','"','');fclose($h);abort_unless(is_array($headers)&&count($headers)<=30,422,'Use a CSV header row with up to 30 columns.');$headers[0]=preg_replace('/^\xEF\xBB\xBF/','',$headers[0]);abort_unless(mb_check_encoding(implode('',$headers),'UTF-8')&&collect($headers)->every(fn($v)=>is_string($v)&&trim($v)!==''&&mb_strlen($v)<=100),422,'Use UTF-8 column names of up to 100 characters.');abort_if(count(array_unique($headers))!==count($headers),422,'Use unique column names.');foreach($d['mapping'] as $header)abort_if($header&&!in_array($header,$headers,true),422,'Choose columns from this file.');abort_unless(!empty($d['mapping']['email'])||!empty($d['mapping']['phone']),422,'Map an email or international phone column.');$path=$f->store('marketing-audience/uploads','local');try{$id=$this->tasks()->start($r->user(),'import',['path'=>$path,'headers'=>$headers,'mapping'=>$d['mapping'],'stage'=>'preview']);}catch(\Throwable $e){Storage::disk('local')->delete($path);throw $e;}return response()->json(['id'=>$id],202);
 }
 public function export(Request $r){$this->access($r,Permission::EXPORT_AUDIENCE);$f=$this->filters(new Request($r->input('filters',[])));$r->validate(['segment'=>'nullable|uuid','columns'=>'sometimes|array|min:1|max:5','columns.*'=>['string',Rule::in(['name','email','phone','paid_orders','enquiries'])]]);$d=['filters'=>$f,'segment'=>$r->input('segment'),'columns'=>$r->input('columns',['name','email','phone','paid_orders','enquiries'])];if($d['segment'])$this->segment($d['segment']);abort_if($this->tasks()->exportQuery($d)->count()>50000,422,'Narrow your selection to 50,000 contacts or fewer.');return response()->json(['id'=>$this->tasks()->start($r->user(),'export',$d)],202);}
 public function recent(Request $r){$this->access($r);$d=$r->validate(['kind'=>'required|in:sync,import,export']);$q=DB::table('marketing_audience_tasks')->where('merchant_key',$this->dir()->merchant())->where('kind',$d['kind']);if(!$r->user()->is_super_admin&&$d['kind']!=='sync')$q->where('user_id',$r->user()->id);return response()->json(['data'=>$q->select(['id','kind','state','processed','valid','invalid','created_at','expires_at'])->latest('created_at')->limit(20)->get()]);}
 public function status(Request $r,string $id){$this->access($r);$t=$this->task($r,$id);$d=(array)$t;unset($d['payload']);if($t->kind==='sync'){$d['checkpoint']=$this->tasks()->checkpoint($t);$stage=(int)(json_decode($t->payload,true)['stage']??0);$d['progress_percent']=$t->state==='completed'?100:min(95,(int)floor($stage/7*100));}$d['rows']=[];$d['imported']=$t->kind==='import'?DB::table('marketing_audience_import_rows')->where('task_id',$id)->where('status','imported')->count():0;if($t->kind==='import'&&$t->user_id===$r->user()->id){$d['rows']=DB::table('marketing_audience_import_rows')->where('task_id',$id)->orderBy('row_number')->limit(15)->get()->map(function($row){$row->data=json_decode($row->data,true);return $row;});}$d['downloadable']=$t->kind==='export'&&$t->state==='completed'&&now()->lessThan($t->expires_at)&&Permission::allows($r->user(),Permission::EXPORT_AUDIENCE);return response()->json($d);}
 public function continueSync(Request $r,string $id){
  $this->access($r,Permission::MANAGE_AUDIENCE);$t=$this->task($r,$id);abort_unless($t->kind==='sync',404);$d=$r->validate(['checkpoint'=>'required|string|size:64|regex:/^[a-f0-9]+$/']);
  $this->tasks()->step($id,true,$d['checkpoint']);return $this->status($r,$id);
 }
 public function confirm(Request $r,string $id){$this->access($r,Permission::MANAGE_AUDIENCE);$t=$this->task($r,$id);abort_unless($t->kind==='import',404);$this->tasks()->confirm($id);return response()->json(['id'=>$id],202);}
 public function download(Request $r,string $id){$this->access($r,Permission::EXPORT_AUDIENCE);$t=$this->task($r,$id);abort_unless($t->kind==='export'&&$t->state==='completed',409,'This export is not ready.');abort_if(now()->greaterThan($t->expires_at),410,'This export expired. Prepare a new export.');$this->tasks()->audit($r->user()->id,'export_downloaded',$id,['rows'=>$t->processed]);$columns=json_decode($t->payload,true)['columns']??['name','email','phone','paid_orders','enquiries'];$labels=['name'=>'Name','email'=>'Email','phone'=>'Phone','paid_orders'=>'Verified paid orders','enquiries'=>'Enquiries'];$headers=array_map(fn($k)=>$labels[$k],$columns);try{$paths=$this->tasks()->verifyExportParts($id,json_decode($t->payload,true),$t->processed);}catch(\Throwable){abort(409,'This export is incomplete. Prepare a new export; your contacts are retained.');}return response()->streamDownload(function()use($paths,$headers){$out=fopen('php://output','w');fputcsv($out,$headers,',','"','');foreach($paths as $p){$in=Storage::disk('local')->readStream($p);if(!$in)throw new \RuntimeException('Export file became unavailable.');stream_copy_to_stream($in,$out);fclose($in);}fclose($out);},'audience.csv',['Content-Type'=>'text/csv; charset=UTF-8','Cache-Control'=>'private, no-store']);}
 public function errors(Request $r,string $id){$this->access($r,Permission::MANAGE_AUDIENCE);$t=$this->task($r,$id);abort_unless($t->kind==='import',404);abort_if(now()->greaterThan($t->expires_at),410);return response()->streamDownload(function()use($id){$h=fopen('php://output','w');fputcsv($h,['Row','Reason'],',','"','');DB::table('marketing_audience_import_rows')->where('task_id',$id)->where('status','invalid')->orderBy('id')->chunkById(100,function($rows)use($h){foreach($rows as $r)fputcsv($h,[$r->row_number,$r->error],',','"','');});fclose($h);},'import-errors.csv',['Cache-Control'=>'private, no-store']);}
 private function filters(Request $r):array{return $r->validate(['q'=>'nullable|string|max:120','source'=>['nullable',Rule::in(['customer','order','enquiry','newsletter','import'])],'activity'=>['nullable',Rule::in(['paid','enquiry'])],'subscription'=>['nullable',Rule::in(['subscribed','unknown','unsubscribed','suppressed'])],'per_page'=>['nullable',Rule::in([25,50,100])]]);}
}
